// Types for designely-runtime.js, the Designely Studio engine. Generated by Designely Studio.

/** A scene document: its artboard and layers, as Designely Studio exports it. */
export interface DesignelyScene {
  readonly schemaVersion: number;
  readonly canvas: { readonly width: number; readonly height: number; readonly [key: string]: unknown };
  readonly layers: readonly DesignelyLayer[];
  readonly [key: string]: unknown;
}

export interface DesignelyLayer {
  readonly id: string;
  readonly kind: string;
  readonly params: Readonly<Record<string, unknown>>;
  readonly [key: string]: unknown;
}

/** An effect's shaders and settings (a component's `.effect.ts` file). */
export interface DesignelyEffect {
  readonly id: string;
  readonly [key: string]: unknown;
}

/** A running scene. */
export interface DesignelyHandle {
  /** Shows another version of the scene (new settings) without restarting it. */
  update(scene: DesignelyScene): void;
  pause(): void;
  play(): void;
  /** Stops the scene and removes its canvas. */
  destroy(): void;
}

export interface DesignelyMountOptions {
  /** The effects the scene uses. */
  effects?: readonly DesignelyEffect[];
  /** Modules the component needs; a missing one is warned about once. */
  requires?: readonly string[];
}

/** The engine's modules besides its core. */
export declare const DESIGNELY_RUNTIME_MODULES: readonly string[];

/** Starts a scene in `element`; null if it couldn't start (no WebGL2, say). Never throws. */
export declare function mountDesignely(element: HTMLElement, scene: DesignelyScene, options?: DesignelyMountOptions): DesignelyHandle | null;
